def longestSubstring(s: str, k: int) -> int:
    def helper(sub):
        if len(sub) < k:
            return 0
        count = {}
        for c in sub:
            count[c] = count.get(c, 0) + 1

        split_char = None
        for c in count:
            if count[c] < k:
                split_char = c
                break

        if split_char is None:
            return len(sub)

        parts = sub.split(split_char)
        return max(helper(part) for part in parts)

    return helper(s)
